#!/usr/bin/env node
"use strict";

const initWizard = require("../src/init");
const setupSkill = require("../src/setup");
const path = require("path");

const PACKAGE_ROOT = path.join(__dirname, "..");

/**
 * npm 安装完成后自动把 SKILL.md 分发到各 AI 助手的 skills 目录（agents 实体 + 软链接），
 * 使 "npm install -g @latest" 一步完成 CLI 与 AI skill 的同步升级；失败不阻塞安装。
 * 幂等：重复安装/升级会重建实体与软链（Windows 无符号链接权限时自动退化为复制）。
 */
function autoInstallSkills() {
  try {
    const results = setupSkill.install(PACKAGE_ROOT, { agent: "all" });
    const canonical = results.find((r) => r.agent === "agents");
    const links = results.filter((r) => r.agent !== "agents");
    const anyFallback = links.some((r) => r.fallback);
    const names = links.map((r) => r.agent).join("/");
    const done = canonical && links.length ? `agents (实体), ${names} (软链接)` : canonical ? "agents (实体)" : names;
    console.log(`rrs AI skill 已同步: ${done}${anyFallback ? " — Windows 已自动 fallback 为复制（开启开发者模式可获得真软链接）" : ""}`);
  } catch (e) {
    console.error(`[rrs postinstall] AI skill 自动分发失败（不影响 CLI 使用）: ${e.message}`);
    console.error("可稍后手动执行: rrs setup skills");
  }
}

(async () => {
  autoInstallSkills();
  const tty = process.stdin.isTTY && process.stdout.isTTY;
  if (tty) {
    try {
      await initWizard.runInteractive({ packageRoot: PACKAGE_ROOT });
    } catch (e) {
      console.error(`[rrs postinstall] 向导失败: ${e.message}`);
      console.error("可稍后手动执行: rrs init");
    }
  } else {
    console.log("");
    console.log("rrs 安装完成。下一步:");
    console.log("  rrs init                # 交互式初始化配置（首次安装必跑；向导不再询问 skill 安装，见上）");
    console.log("  rrs setup skills --agent opencode   # 如需只分发部分 AI 助手（默认已全量分发）");
