#!/usr/bin/env node
"use strict";

const fs = require("fs");
const path = require("path");
const { loadConf, configDir, audit, validateConfig } = require("../src/config");
const { JumpShell, cleanAnsi } = require("../src/jumpshell");
const {
  validateCmd, validatePath, validateHost, validateArg, validateBin,
} = require("../src/whitelist");
const setupSkill = require("../src/setup");
const initWizard = require("../src/init");
const transfer = require("../src/transfer");

const PACKAGE_ROOT = path.join(__dirname, "..");

function printUsage() {
  const cmds = [
    ["init", "交互式初始化向导（TTY 下）或生成配置模板"],
    ["list-tools", "查看工具、白名单、配置"],
    ["sys-info", "主机名/OS/内核/uptime"],
    ["proc <pattern>", "进程查询（防注入参数校验）"],
    ["ports [filter]", "监听端口查询"],
    ["read-file <path>", "读文件（路径白名单）"],
    ["dir <path>", "列目录（路径白名单）"],
    ["bin-version <bin>", "查二进制版本（二进制白名单）"],
    ["exec-only <cmd>", "通用只读命令（前缀白名单+禁止模式）"],
    ["download <远程> <本地>", "下载单文件（SFTP，仅 direct 主机；内置敏感路径防呆）"],
    ["upload <本地> <远程>", "上传单文件（SFTP，默认禁用需配置开启 + 写路径白名单）"],
    ["setup skills [--agent <n>]", "把 SKILL.md 装到 agents(实体) + opencode/claude/qoder(软链接)"],
    ["setup uninstall skills [--agent <n>]", "移除上述目录的 skill"],
  ];
  console.log("rrs — CLI and Agent Skill for safe read-only SSH inspection\n");
  console.log("用法: rrs <工具> [参数] [--host <ip>] [--config <file>] [--json]");
  console.log("      rrs download <远程绝对路径> <本地绝对路径> [--overwrite|--resume] [--host <ip>]");
  console.log("      rrs upload <本地绝对路径> <远程绝对路径> [--overwrite|--resume] [--host <ip>]");
  console.log("      rrs setup skills [--agent opencode|claude|cursor|windsurf|codex|openhands|agents|all] [--dry-run]\n");
  console.log("选项: --json 以 JSON 输出结果（便于脚本/AI 调用）; --overwrite 重传; --resume 断点续传; -v/--version 查看版本\n");
  for (const [k, v] of cmds) {
    console.log(`  ${k.padEnd(40)} ${v}`);
  }
}

function parseArgs(argv) {
  const opts = {
    mode: "tool",
    tool: null,
    arg: null,
    setupCmd: null,
    agent: "all",
    dryRun: false,
    host: null,
    config: null,
    version: false,
    json: false,
    overwrite: false,
    resume: false,
  };
  const rest = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--host") opts.host = argv[++i];
    else if (a === "--config") opts.config = argv[++i];
    else if (a === "--agent") opts.agent = argv[++i];
    else if (a === "--dry-run") opts.dryRun = true;
    else if (a === "--overwrite") opts.overwrite = true;
    else if (a === "--resume") opts.resume = true;
    else if (a === "-h" || a === "--help") { opts.mode = "tool"; opts.tool = "help"; }
    else if (a === "-v" || a === "--version") opts.version = true;
    else if (a === "--json") opts.json = true;
    else rest.push(a);
  }
  if (rest[0] === "setup") {
    opts.mode = "setup";
    if (rest[1] === "uninstall") {
      opts.setupCmd = "uninstall";
      if (rest[2] === "skills") opts.setupTarget = "skills";
    } else if (rest[1] === "skills") {
      opts.setupCmd = "install";
      opts.setupTarget = "skills";
    }
    return opts;
  }
  opts.tool = opts.tool || rest[0] || "help";
  opts.arg = rest[1] || null;
  opts.arg2 = rest[2] || null;
  return opts;
}

function runSetup(opts) {
  const agent = opts.agent || "all";
  if (!opts.setupTarget || opts.setupTarget !== "skills") {
    console.error("用法: rrs setup skills [--agent all|opencode|claude|claudecode|cursor|windsurf|codex|qoder|agents|openhands] [--dry-run]");
    console.error("      rrs setup uninstall skills [--agent ...] [--dry-run]");
    process.exit(1);
  }
  let results;
  try {
    results = opts.setupCmd === "uninstall"
      ? setupSkill.uninstall({ agent, dryRun: opts.dryRun })
      : setupSkill.install(PACKAGE_ROOT, { agent, dryRun: opts.dryRun });
  } catch (e) {
    console.error(`[setup] 错误: ${e.message}`);
    process.exit(1);
  }

  if (opts.dryRun) {
    console.log(opts.setupCmd === "uninstall" ? "将卸载:" : "将安装:");
    for (const r of results) {
      console.log(`  ${r.action.replace("would-", "将")} ${r.dir}`);
    }
    return;
  }

  // 默认输出：一行简明
  const canonical = results.find((r) => r.agent === "agents");
  const links = results.filter((r) => r.agent !== "agents");
  const linkNames = links.map((r) => r.agent).join("/");
  const anyFallback = links.some((r) => r.fallback);
  const verb = opts.setupCmd === "uninstall" ? "已卸载" : "已安装";

  if (opts.setupCmd === "install") {
    if (canonical && links.length > 0) {
      console.log(`rrs skill ${verb}: agents (实体), ${linkNames} (软链接)${anyFallback ? " — Windows 已自动 fallback 为复制（请开启开发者模式以启用真软链接）" : ""}`);
    } else if (canonical) {
      console.log(`rrs skill ${verb}: agents (实体)`);
    } else if (links.length > 0) {
      console.log(`rrs skill ${verb}: ${linkNames} (软链接)${anyFallback ? " — Windows 已自动 fallback 为复制" : ""}`);
    }
  } else {
    const removed = results.filter((r) => r.action !== "missing").map((r) => r.agent).join("/");
    if (removed) console.log(`rrs skill ${verb}: ${removed}`);
    else console.log(`rrs skill 未找到任何已安装项`);
  }
}

function initConfig() {
  if (process.stdin.isTTY && process.stdout.isTTY) {
    return initWizard.runInteractive().catch((e) => {
      console.error(`[init] ${e.message}`);
      process.exit(1);
    });
  }
  const dir = configDir();
  const dest = path.join(dir, "config.json");
  if (fs.existsSync(dest)) {
    console.log(`配置已存在: ${dest}（未覆盖，如需重置请手动删除）`);
    return;
  }
  const tpl = fs.readFileSync(path.join(PACKAGE_ROOT, "config.example.json"), "utf8");
  fs.writeFileSync(dest, tpl, "utf8");
  console.log(`已生成配置模板: ${dest}`);
  console.log("请填写 auth_profiles（认证组：SSH 私钥或密码）、target_hosts（目标主机）后使用。");
}

function buildCmds(tool, arg, conf) {
  switch (tool) {
    case "sys-info":
      return [
        "echo ===HOST===; hostname; whoami; id",
        "echo ===OS===; head -5 /etc/os-release 2>&1",
        "echo ===KERNEL===; uname -a",
        "echo ===UPTIME===; uptime",
      ];
    case "proc":
      return [`ps -ef | grep -E '${validateArg(arg, "进程名")}' | grep -v grep`];
    case "ports":
      return arg
        ? [`ss -tln | grep '${validateArg(arg, "端口过滤")}'`]
        : ["ss -tln"];
    case "read-file":
      return [`cat ${validatePath(arg, conf)}`];
    case "dir":
      return [`ls -la ${validatePath(arg, conf)}`];
    case "bin-version":
      return [`${validateBin(arg, conf)} -v 2>&1`, `${validateBin(arg, conf)} -V 2>&1`];
    case "exec-only":
      return [validateCmd(arg, conf)];
    default:
      throw new Error(`未知工具 [${tool}]，用 list-tools 查看`);
  }
}

function listTools(conf) {
  console.log("可用工具:");
  const tools = {
    "sys-info": "主机名/OS/内核/uptime",
    "proc <pattern>": "进程查询",
    "ports [filter]": "端口查询",
    "read-file <path>": "读文件（路径白名单）",
    "dir <path>": "列目录",
    "bin-version <bin>": "查版本（二进制白名单）",
    "exec-only <cmd>": "通用只读命令（白名单校验）",
    "download <远程> <本地>": "下载单文件（SFTP：direct 直连或 koko 网关）",
    "upload <本地> <远程>": "上传单文件（写操作，opt-in + 写路径白名单）",
  };
  for (const [k, v] of Object.entries(tools)) console.log(`  ${k.padEnd(20)} ${v}`);
  const profiles = conf.auth_profiles || {};
  console.log(`\n认证组: ${Object.entries(profiles).map(([id, p]) => `${id}(${p.auth.mode}@${p.host}${p.direct ? ",direct" : ""})`).join(", ") || "(无)"}`);
  console.log(`允许主机: ${Object.keys(conf.target_hosts || {}).join(", ")}`);
  console.log(`允许查版本: ${(conf.allowed_version_bins || []).join(", ")}`);
  console.log(`允许读路径前缀: ${(conf.allowed_path_prefixes || []).join(", ")}`);
  const ft = conf.file_transfer || {};
  const upEnabled = ft.upload && ft.upload.enabled === true;
  const upPrefixes = (ft.upload && ft.upload.allowed_path_prefixes || []).join(", ") || "(未配置=全禁)";
  console.log(`文件传输: 下载=可用（内置敏感路径防呆） | 上传=${upEnabled ? `启用（写路径前缀: ${upPrefixes}）` : "禁用（file_transfer.upload.enabled=true 开启）"}`);
  console.log(`配置文件: ${process.env.RRS_CONFIG || path.join(configDir(), "config.json")}`);
  console.log(`审计日志: ${path.join(configDir(), "audit.log")}`);
}

function emitResult(opts, data) {
  if (opts.json) console.log(JSON.stringify(data));
  else if (data.error) console.error(`[${data.kind || "错误"}] ${data.error}`);
  else console.log(data.output);
}

// ==== 文件传输（upload / download）====

function fmtBytes(n) {
  const units = ["B", "KiB", "MiB", "GiB", "TiB"];
  let v = Number(n) || 0;
  let i = 0;
  while (v >= 1024 && i < units.length - 1) { v /= 1024; i++; }
  return `${v >= 100 || i === 0 ? Math.round(v) : v.toFixed(1)} ${units[i]}`;
}

function fmtDur(ms) {
  const s = Math.round(ms / 1000);
  if (s < 60) return `${s}s`;
  const m = Math.floor(s / 60);
  return `${m}m${String(s % 60).padStart(2, "0")}s`;
}

/** 进度只打到 stderr（不污染 --json 的 stdout），且仅终端场景显示 */
function makeProgress(opts) {
  if (opts.json || !process.stderr.isTTY) return null;
  const startedAt = Date.now();
  return (sent, total) => {
    const pct = total > 0 ? ((sent / total) * 100).toFixed(1) : "-";
    const speed = sent / 1048576 / Math.max(0.25, (Date.now() - startedAt) / 1000);
    process.stderr.write(`  已传 ${fmtBytes(sent)} / ${fmtBytes(total)}（${pct}%，~${speed.toFixed(1)} MiB/s）   \r`);
  };
}

async function runTransfer(opts, conf) {
  const tool = opts.tool;
  const isUpload = tool === "upload";
  // 语义：upload <本地> <远程>；download <远程> <本地>
  const args = isUpload
    ? { local: opts.arg, remote: opts.arg2, overwrite: opts.overwrite, resume: opts.resume }
    : { remote: opts.arg, local: opts.arg2, overwrite: opts.overwrite, resume: opts.resume };

  // ---- 静态校验（拒绝类：退出码 2）----
  let host = null;
  let cmds = [];
  let plan;
  try {
    host = validateHost(opts.host || Object.keys(conf.target_hosts || {})[0], conf);
    cmds = [isUpload
      ? `upload ${args.local || "(无)"} -> ${args.remote || "(无)"}`
      : `download ${args.remote || "(无)"} -> ${args.local || "(无)"}`];
    plan = transfer.prepareTransfer(conf, host, tool, args);
  } catch (e) {
    audit(conf, tool, host || "", cmds, false, e.message);
    emitResult(opts, { ok: false, tool, host: host || "", error: e.message, kind: "拒绝" });
    process.exit(2);
  }

  // ---- 连接与执行（错误类：退出码 1）----
  const shell = new JumpShell(conf, host);
  try {
    await shell.connect(); // direct 连接即到目标机，无需菜单 login
    const onProgress = makeProgress(opts);
    const result = isUpload
      ? await transfer.uploadFile(shell, conf, plan, onProgress)
      : await transfer.downloadFile(shell, conf, plan, onProgress);
    shell.close();
    try { if (onProgress) process.stderr.write("\n"); } catch (_) {}

    const speedBps = result.bytes / Math.max(0.001, result.elapsedMs / 1000);
    const resumeTag = result.resumed ? "（断点续传）" : "";
    const viaTag = plan.mode === "koko" ? "（koko 资产树直传）" : "";
    const verifyTag = result.verify === "sha256" ? "，sha256 校验通过" : "，已核落地字节数";
    const fallbackTag = result.fallbackError ? `，fast 通道回退：${result.fallbackError}` : "";
    const text = `${isUpload ? "上传" : "下载"}完成: ${plan.local} ↔ ${plan.remote} | ${fmtBytes(result.bytes)} 耗时 ${fmtDur(result.elapsedMs)} 均 ${(speedBps / 1048576).toFixed(1)} MiB/s${resumeTag}${viaTag}${verifyTag}${fallbackTag}`;
    audit(conf, tool, host, cmds, true,
      `bytes=${result.bytes}${result.expected !== undefined ? `/${result.expected}` : ""} elapsed=${result.elapsedMs}ms resumed=${result.resumed} verify=${result.verify} transport=${result.transport || "-"}${result.fallbackError ? ` fastErr=${result.fallbackError}` : ""} overwrite=${plan.flags.overwrite} via=${plan.mode}`);
    emitResult(opts, {
      ok: true, tool, host,
      local: plan.local, remote: plan.remote,
      bytes: result.bytes, expected: result.expected, resumed: result.resumed,
      elapsed_ms: result.elapsedMs, verify: result.verify,
      transport: result.transport, fallback_error: result.fallbackError || undefined,
      overwrite: plan.flags.overwrite, via: plan.mode,
      output: text,
    });
  } catch (e) {
    shell.close();
    try { if (!opts.json && process.stderr.isTTY) process.stderr.write("\n"); } catch (_) {}
    audit(conf, tool, host, cmds, false, e.message);
    emitResult(opts, { ok: false, tool, host, error: e.message, kind: "错误" });
    process.exit(1);
  }
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  if (opts.version) {
    console.log(require(path.join(PACKAGE_ROOT, "package.json")).version);
    return;
  }
  if (opts.mode === "setup") { runSetup(opts); return; }
  if (opts.tool === "help") { printUsage(); return; }
  if (opts.tool === "init") { initConfig(); return; }

  let conf;
  try {
    conf = loadConf(opts.config);
  } catch (e) {
    emitResult(opts, { ok: false, error: e.message, kind: "错误" });
    process.exit(e.exitCode || 1);
  }

  try {
    validateConfig(conf);
  } catch (e) {
    emitResult(opts, { ok: false, error: e.message, kind: "错误" });
    process.exit(e.exitCode || 1);
  }

  if (opts.tool === "list-tools") { listTools(conf); return; }
  if (opts.tool === "upload" || opts.tool === "download") { await runTransfer(opts, conf); return; }

  let host, cmds;
  try {
    host = validateHost(opts.host || Object.keys(conf.target_hosts || {})[0], conf);
    cmds = buildCmds(opts.tool, opts.arg, conf);
  } catch (e) {
    audit(conf, opts.tool, opts.host || "", [], false, e.message);
    emitResult(opts, { ok: false, tool: opts.tool, host: opts.host || "", error: e.message, kind: "拒绝" });
    process.exit(2);
  }

  const shell = new JumpShell(conf, host);
  try {
    await shell.connect();
    await shell.login();
    const out = await shell.runCmds(cmds);
    const cleaned = cleanAnsi(out);
    emitResult(opts, { ok: true, tool: opts.tool, host, output: cleaned });
    audit(conf, opts.tool, host, cmds, true, undefined, cleaned);
  } catch (e) {
    audit(conf, opts.tool, host, cmds, false, e.message);
    emitResult(opts, { ok: false, tool: opts.tool, host, error: e.message, kind: "错误" });
    process.exit(1);
  } finally {
    shell.close();
  }
}

if (require.main === module) {
  main();
}

module.exports = { parseArgs, buildCmds, printUsage, runSetup, initConfig };
